public class Main {
    public static void main(String[] args) {
        int number = 1;
        int total = 0;
        while (number <= 4) {
            total += number;
            number++;
        }
        System.out.println(total);
    }
}

public class Main {
    public static void main(String[] args) {
        int count = 1;
        while (count <= 5) {
            if (count == 3) {
                break;
            }
            System.out.println(count);
            count++;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int count = 0;
        while (count < 4) {
            count++;
            if (count == 2) {
                continue;
            }
            System.out.println(count);
        }
    }
}
